/* msimd6.c — OTT (win64 VST2) lift の __asm_* helpers 完全版。
 * generated by gen_msimd6.py from: work/ott_shift3b.ll
 *  - signature: lift IR 宣言そのまま (RetDec の i64/i32 返り値・i64 即値引数を保持)
 *  - i256 (vmovdqu/vmovdqa/vmovntdq) は定義しない: 呼出 site は m6_memfix.py が
 *    CRT memmove C 実装化により消滅させる (m6_simd_check.py で残呼出 0 を検収)。
 *  - comis/ucomis 系は no-op (CF/ZF/PF は ir6_pass.py [P1] が IR 内で fcmp 化)
 *  - mxcsr 系は no-op (wasm では rounding/例外マスク制御不可; native は DLL 実機)
 */
#include "msimd8_core.h"

/* --- M8 デバッグ追跡器 (ring: 直近 512 事象, NaN birth 記録) --- */
#include <string.h>
extern unsigned g_msg[]; extern unsigned g_msg_n;
extern unsigned g_born[8]; extern unsigned g_born_n;
static void m8nan(unsigned op, unsigned a, unsigned b, unsigned r) {
    unsigned idx = (g_msg_n % 512u) * 4u;
    g_msg[idx] = op; g_msg[idx+1] = a; g_msg[idx+2] = b; g_msg[idx+3] = r;
    g_msg_n++;
    int nana = ((a & 0x7f800000u) == 0x7f800000u && (a & 0x007fffffu));
    int nanb = ((b & 0x7f800000u) == 0x7f800000u && (b & 0x007fffffu));
    int nanr = ((r & 0x7f800000u) == 0x7f800000u && (r & 0x007fffffu));
    if (nanr && !nana && !nanb && g_born_n + 4 <= 8) {   /* 出生 op (入力非 NaN) */
        g_born[g_born_n] = op; g_born[g_born_n+1] = a; g_born[g_born_n+2] = b; g_born[g_born_n+3] = r;
        g_born_n += 4;
    }
}
EMSCRIPTEN_KEEPALIVE unsigned m8dbg_n(void) { return g_msg_n; }
/* 絶対番号 e 事象の word k を ring 経由で返す (直近 512 事象のみ有効) */
EMSCRIPTEN_KEEPALIVE unsigned m8dbg(unsigned e4) { return g_msg[(e4 % 2048u)]; }
EMSCRIPTEN_KEEPALIVE unsigned m8dbg_born_n(void) { return g_born_n; }
EMSCRIPTEN_KEEPALIVE unsigned m8dbg_born(unsigned i) { return i < 8 ? g_born[i] : 0; }


